SET NOCOUNT ON;SET XACT_ABORT ON;SET DEADLOCK_PRIORITY LOW;
BEGIN TRY BEGIN TRAN;UPDATE lab.DeadlockRows SET Value+=1 WHERE RowId=1;EXEC fwk.USP_Signal '$(DemoId)','$(RunToken)','A_LOCKED';EXEC fwk.USP_WaitForSignal '$(DemoId)','$(RunToken)','B_LOCKED',15000;UPDATE lab.DeadlockRows SET Value+=1 WHERE RowId=2;COMMIT;INSERT lab.Evidence VALUES('ACTOR_A','SURVIVOR',NULL,DEFAULT);END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;IF ERROR_NUMBER()<>1205 THROW;INSERT lab.Evidence VALUES('ACTOR_A','VICTIM',1205,DEFAULT);END CATCH;EXEC fwk.USP_Signal '$(DemoId)','$(RunToken)','A_DONE';PRINT 'SQLPERF_SUMMARY|PASS|OK';
